from lib import *
S = SS('x10')
steps = [
    step("@Profile。7 个 @Bean(dev、prod、!prod、default、\"dev & !cloud\"、\"prod | cloud\"、不带 @Profile 的 always)。什么都不激活时默认 profile 是 default,留下 [always, notProd, onlyDefault]。激活 dev:default 失效,留下 [always, dev, devNotCloud, notProd]。激活 prod:[always, prod, prodOrCloud]。激活 dev 加 cloud:devNotCloud 被排除,留下 [always, dev, notProd, prodOrCloud]。-Dspring.profiles.active=dev 与代码里 setActiveProfiles(dev) 结果相同。setDefaultProfiles(base) 之后没有激活:default 这个名字的 Bean 也没了,只剩 [always, notProd]。", t=tl(S(1)), mark=lidx(S(1), '激活 [dev, cloud]', '默认 [base]'), done=lidx(S(1), '什么都不激活', 'setActiveProfiles(dev):', 'setActiveProfiles(prod)', '-Dspring.profiles.active=dev'), b=bars([['什么都不激活:留下的 Bean', 3, '3'], ['激活 dev:留下', 4, '4'], ['激活 prod:留下', 3, '3'], ['激活 dev + cloud:留下', 4, '4'], ['默认 profile 改成 base:留下', 2, '2']], 4, done=[0, 1, 2], mark=[3, 4]), kv=KV([['没有激活', '默认 profile = default'], ['一旦激活别的', 'default 就失效'], ['表达式', 'dev & !cloud、prod | cloud 可用'], ['属性方式', '-Dspring.profiles.active 与 setActiveProfiles 等效']], ['一旦激活别的'])),
    step("条件对注册顺序敏感。FallbackBean 里的 @Bean 条件是“registry 里没有 dataSource 才注册 fallbackDs”,User 里有一个 dataSource。注册顺序 [User, FallbackBean]:条件求值时 registry 里已有 dataSource = true,不注册 fallbackDs,留下 [dataSource]。注册顺序 [FallbackBean, User]:求值时 dataSource = false,fallbackDs 被注册,留下 [dataSource, fallbackDs]。这就是“按 Bean 存在与否”判断的条件(Boot 的 OnMissingBean 同理)要依赖配置类顺序的原因。", t=tl(S(2)), mark=lidx(S(2), '注册顺序 [FallbackBean, User]'), done=lidx(S(2), '注册顺序 [User, FallbackBean]'), b=bars([['User 先注册:fallbackDs 存在', 0, '否'], ['Fallback 先注册:fallbackDs 存在', 1, '是(同时有两个数据源)']], 1, done=[0], mark=[1]), kv=KV([['User 先', '[dataSource]'], ['Fallback 先', '[dataSource, fallbackDs]'], ['求值时看到', 'true / false(随顺序变)'], ['含义', '“缺失才注册”依赖顺序']], ['含义'])),
    step("配置类上的条件(ConfigurationCondition,PARSE_CONFIGURATION 阶段)求值得更早。FallbackParse 把同样的“registry 里没有 dataSource 才生效”放在 @Configuration 类上:不管注册顺序是 [User, FallbackParse] 还是 [FallbackParse, User],条件都被求值了 2 次,每次看到的 dataSource 都是 false,所以 fallbackDsParse 都被注册,最后总是 [dataSource, fallbackDsParse]。@Bean 方法定义要等配置类解析完才注册进 registry,类级别的条件看不到它们。", t=tl(S(3)), mark=lidx(S(3), 'MissingDsParse(PARSE_CONFIGURATION 阶段)被求值'), done=lidx(S(3), '注册顺序 [User, FallbackParse]', '注册顺序 [FallbackParse, User]'), b=bars([['User 先:fallbackDsParse 存在', 1, '是(条件看不到 dataSource)'], ['Fallback 先:fallbackDsParse 存在', 1, '是'], ['条件被求值的次数', 2, '2']], 2, mark=[0, 1], cur=[2]), kv=KV([['PARSE_CONFIGURATION', '配置类解析阶段,看不到 @Bean 的定义'], ['REGISTER_BEAN', '注册 Bean 定义时,看得到先注册的'], ['结果', '类上的条件不受顺序影响,但看不到 @Bean'], ['求值次数', '2 次']], ['PARSE_CONFIGURATION'])),
    step("条件放在类上还是方法上。ClassOff 的类上是 @Conditional(false),它带的 @Import(Imported)、嵌套的配置类 Nested、自己的 @Bean inOff 全部没有注册。MethodOff 里方法上有 @Conditional(false) 的 @Bean dropped 没有注册,没有条件的 keep 保留。两个配置类一起注册后,容器里只剩 [keep]。", t=tl(S(4)), mark=lidx(S(4), '剩下 → [keep]'), b=bars([['ClassOff 的 3 个来源', 0, '全部没有注册(inOff、importedBean、nestedBean)'], ['MethodOff 的 keep', 1, '保留'], ['MethodOff 的 dropped', 0, '没有注册']], 1, mark=[0, 2], done=[1]), kv=KV([['类上 @Conditional', '整个类、@Import、嵌套类都跳过'], ['方法上 @Conditional', '只影响这个 @Bean'], ['最终剩下', '[keep]'], ['提示', '类级别的条件可以一次关掉一整组配置']], ['类上 @Conditional'])),
]
A = mkartx('x10', 10, 'Spring,Conditional,Profile,条件装配,真实验证,动画演示',
    '实测 @Profile 与 @Conditional:没有激活 profile 时默认是 default,一旦激活别的 default 就失效;"dev & !cloud" 这样的表达式可用;“registry 里没有才注册”的条件依赖配置类顺序(User 先 [dataSource],Fallback 先 [dataSource, fallbackDs]);类级别条件在 PARSE_CONFIGURATION 阶段求值,看不到 @Bean 的定义;类上的条件会一次跳过 @Import 和嵌套配置类。',
    '@Profile 到底怎么选?默认 profile 什么时候失效?自定义 @Conditional 为什么会随配置类顺序变化?类上和方法上的条件有什么区别?这篇在 Spring Framework 7.0.9 上把条件装配的几个坑逐个跑出来。',
    [('default', '没有激活任何 profile 时的默认 profile;激活别的 profile 后它就不再生效'), ('2 种', '同样的“没有 dataSource 才注册”,在不同注册顺序下得到 [dataSource] 与 [dataSource, fallbackDs]'), ('[keep]', '类上和方法上的 @Conditional(false) 之后,容器里剩下的 Bean')],
    [('Profile', '<p>没有激活时用 default;激活了别的 profile,default 就不再生效;支持 &、|、! 表达式。</p>'),
     ('条件与顺序', '<p>“缺失才注册”类的条件依赖配置类的注册顺序。</p>'),
     ('求值阶段', '<p>类上的 ConfigurationCondition 在解析阶段求值,看不到 @Bean 方法注册的定义。</p>'),
     ('类上与方法上', '<p>类上的 @Conditional 一次跳过整个类及其 @Import 与嵌套配置类。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9 的 AnnotationConfigApplicationContext(Boot 的 @ConditionalOnMissingBean 等在后面的 Boot 篇讲);第一节的 -Dspring.profiles.active 是通过 JVM 系统属性传的',
     '没有验证:Boot 的 spring.profiles.active 在配置文件、环境变量里的优先级(见 Boot 篇);@Profile 放在 @Component 类上的效果;自定义条件读取 Environment 属性;@ConditionalOnMissingBean 在 Boot 自动配置里怎样靠 @AutoConfiguration 的排序解决顺序问题(见 Boot 篇);条件求值的耗时'],
    '条件装配与 Profile')
